/* 离谱数据的出场表：每条排一个年份，Beta(5,2) 抽，密度峰值在第八世；每世保底一条。
   表是算出来的，不进存档，所以清档、转世都不会乱。 */
const SCHED=(function(){
  const N=FACT.length, PER=75, LIVES=10, SLOTS=PER*LIVES;
  // Beta(4,2) 的分布函数：F(x)=5x^4-4x^5，反解出每一分位落在哪一年
  const F=x=>5*x*x*x*x-4*x*x*x*x*x;
  const inv=p=>{let lo=0,hi=1;for(let i=0;i<60;i++){const mid=(lo+hi)/2;F(mid)<p?lo=mid:hi=mid}return (lo+hi)/2};
  const rows=[];
  for(let i=0;i<N;i++){
    const p=(i+0.5)/N;
    rows.push([i,Math.min(SLOTS-1,Math.floor(Math.min(0.999,inv(p)*1.04)*SLOTS))]);
  }
  const used=new Set();
  rows.forEach(r=>{let s=r[1];while(used.has(s))s=(s+1)%SLOTS;used.add(s);r[1]=s});
  for(let L=0;L<LIVES;L++){
    const lo=L*PER, hi=lo+PER;
    if(rows.some(r=>r[1]>=lo&&r[1]<hi))continue;
    let best=-1,bestCount=1;
    for(let K=0;K<LIVES;K++){
      const cnt=rows.filter(r=>r[1]>=K*PER&&r[1]<(K+1)*PER).length;
      if(cnt>bestCount){bestCount=cnt;best=K}
    }
    if(best<0)continue;
    const cand=rows.filter(r=>r[1]>=best*PER&&r[1]<(best+1)*PER).pop();
    let slot=lo;
    while(used.has(slot)&&slot<hi-1)slot++;
    if(used.has(slot))continue;
    used.delete(cand[1]);used.add(slot);cand[1]=slot;
  }
  const map={};
  rows.forEach(r=>{map[r[1]]=r[0]});
  return map;
})();
