function wpick(str){
  const a=str.split(',').map(x=>{const i=x.lastIndexOf(':');return [x.slice(0,i),+x.slice(i+1)]});
  let t=0;for(const q of a)t+=q[1];
  let r=Math.random()*t;
  for(const q of a){r-=q[1];if(r<0)return q[0]}
  return a[a.length-1][0];
}
