let stIdx=0;
let AC=null,SND=true;
function tone(f,t0,dur,type,gain){
  try{ if(!AC)AC=new (window.AudioContext||window.webkitAudioContext)();
    const o=AC.createOscillator(),g=AC.createGain();
    o.type=type||'sine'; o.frequency.value=f;
    g.gain.setValueAtTime(0,AC.currentTime+t0);
    g.gain.linearRampToValueAtTime(gain||.14,AC.currentTime+t0+.01);
    g.gain.exponentialRampToValueAtTime(.0001,AC.currentTime+t0+dur);
    o.connect(g);g.connect(AC.destination);o.start(AC.currentTime+t0);o.stop(AC.currentTime+t0+dur+.02);
  }catch(e){}
}
function sfx(kind){
  if(!SND)return;
  if(kind==='gong'){tone(196,0,.9,'triangle',.16);tone(293,0,.7,'sine',.07);tone(392,.02,.5,'sine',.04)}
  else if(kind==='tick'){tone(880,0,.05,'square',.03)}
  else if(kind==='end'){tone(146,0,1.4,'triangle',.18);tone(196,.15,1.1,'sine',.08)}
}
