function migrateMile(){
  const legacy=Object.keys(fired).filter(k=>k.charAt(0)==='m'&&k.indexOf('#')<0&&k!=='mallcol1');
  if(!legacy.length)return;
  const byKey={};
  legacy.forEach(k=>{const m=/^m([a-z]+?)(\d+)$/.exec(k);if(!m)return;(byKey[m[1]]=byKey[m[1]]||[]).push([k,+m[2]])});
  Object.keys(byKey).forEach(k=>{
    const tiers=MILE.filter(x=>x[0]===k);
    byKey[k].sort((a,b)=>a[1]-b[1]).forEach((pair,i)=>{
      if(tiers[i])fired[mileId(tiers[i])]=1;
      delete fired[pair[0]];
    });
  });
}
