document.getElementById('bEv').onclick=()=>{
  const order=['死亡','时间','人物','物件','机器','账本','复读','器物与药','离谱'];
  const total=FACT.length;
  const have=FACT.map((f,i)=>[f,got['f'+i]]).filter(r=>r[1]);
  if(!have.length){popup('罪证 0 / '+total,'还一条都没撞见。正月初一才可能掉一条，排到年份的才有，撞见的才记在这里。');return}
  let html='<p>已收集 '+have.length+' / '+total+'。没撞见的不列。</p>';
  order.forEach(g=>{
    const rows=have.filter(r=>r[0][0]===g);
    if(!rows.length)return;
    html+='<h4>'+g+'　'+rows.length+'</h4>'+rows.map(r=>'<p>· '+r[0][1]+(r[0][2]?'　'+r[0][2]:'')+'</p>').join('');
  });
  popup('罪证 '+have.length+' / '+total, html);
};

